# Find all occurrences of the query
query = "Write a short note about a memorable camera lens."
occurrences = []
for i, line in enumerate(lines):
    if line == f"user: {query}":
        occurrences.append(i)
        print(f"Found at line {i}: {repr(line)}")
        if i+1 < len(lines):
            print(f"  Next line (assistant): {repr(lines[i+1])}")

print(f"\nTotal occurrences: {len(occurrences)}")
